var boot_config_aliyunEN = map[string]string{
	"help.boot_config.apply.aliyun.block":                        bootConfigApplyAliyunBlockEN,
	"help.boot_config.apply.aliyun.object":                       bootConfigApplyAliyunObjectEN,
	"cmd.boot_config_top.fetch_oss_resources.aliyun.usage_notes": "Use this command to query the validated Alibaba Cloud object-storage boot-config resources.\n\nParameter source:\n  --cloud-account-id string\n    Comes from `cloud-account list --storage-type object` or `cloud-account detail --id <account_id>`.\n\nReal execution order:\n  1. Resolve the existing target account first.\n  2. Query `regions,zones` and confirm the zone under that account.\n  3. Query `flavors,os_types` with the selected `--zone-id`.\n  4. Query `system_volume_types,volume_types` with `--zone-id` and `--flavor-id`.\n  5. Query `networks` first; then query `subnets,security_groups` with the selected `--zone-id` after you have confirmed the target VPC.\n  6. Continue IP and bandwidth details with `hyperbdrctl boot-config-wizard subnet-config` after `network_id` and `subnet_id` are known.\n\nRun the minimum account-scoped zone query like this:\n  hyperbdrctl boot-config fetch-oss-resources aliyun \\\n    --cloud-account-id <account_id> \\\n    --fetch-res regions,zones \\\n    --output json\n\nThen query flavors and OS types:\n  hyperbdrctl boot-config fetch-oss-resources aliyun \\\n    --cloud-account-id <account_id> \\\n    --fetch-res flavors,os_types \\\n    --zone-id <zone_id> \\\n    --output json\n\nThen query volume types:\n  hyperbdrctl boot-config fetch-oss-resources aliyun \\\n    --cloud-account-id <account_id> \\\n    --fetch-res system_volume_types,volume_types \\\n    --zone-id <zone_id> \\\n    --flavor-id <flavor_id> \\\n    --output json\n\nThen query networks:\n  hyperbdrctl boot-config fetch-oss-resources aliyun \\\n    --cloud-account-id <account_id> \\\n    --fetch-res networks \\\n    --output json\n\nThen query subnets and security groups:\n  hyperbdrctl boot-config fetch-oss-resources aliyun \\\n    --cloud-account-id <account_id> \\\n    --fetch-res subnets,security_groups \\\n    --zone-id <zone_id> \\\n    --output json\n\nDo not treat this command as a replacement for `boot-config-wizard subnet-config`; keep subnet-scoped IP and bandwidth discovery there.\n\nFor scripting against the raw API fields, add:\n  --output json",
}
